8d64581dc1d29648:
#part_page("I", [एक अनुरोध की लागत], [
  कोई एल्गोरिदम चुनने से पहले यह पहचानें कि उसे किस संसाधन की रक्षा करनी है, सुरक्षा तंत्र का संचालन करने में कितना खर्च आता है, और कोई हमलावर कितनी आसानी से उस सुरक्षा को एक महंगे हमले के औज़ार में बदल सकता है।
])

57c9f006a37b51ce:
#objectives([
  इस अध्याय के अंत तक, आप यह गणना करने में सक्षम होंगे कि क्या कोई गेट ओरिजिन के कार्य को बचाता है या नहीं। आप बता सकेंगे कि एक क्लाइंट पहेली (puzzle) क्या स्थापित करती है और क्या नहीं, तथा यह समझा सकेंगे कि सत्यापन की लागत के लिए एक निश्चित सीमा क्यों आवश्यक है।
])

de29137d766efee7:
#definition([विस्तृत उदाहरण: गेट कब अपनी लागत की भरपाई करता है], [
  ⟦0⟧ कार्य इकाइयाँ और ⟦1⟧ चुनें। यदि आधे अनुरोध दुर्भावनापूर्ण हैं, तो गेट की लागत ⟦2⟧ से कम होनी चाहिए। यदि गेट सत्यापन में ⟦3⟧ कार्य इकाइयाँ लगती हैं, तो यह गेट लगाने से ओरिजिन पर लोड कम होने के बजाय बढ़ जाएगा।
])

d2a1e04c685cd3bd:
#definition([विस्तृत उदाहरण: अपेक्षित मान कोई निश्चित समय-सीमा नहीं है], [
  ⟦0⟧ पर अपेक्षित कार्य 65,536 हैश है। इतने प्रयासों के बाद भी खोज जारी रहने की प्रायिकता लगभग ⟦1⟧ है। 95वीं-पर्सेंटाइल प्रयास गणना ⟦2⟧ है, जो औसत से लगभग तीन गुना है। एक उपयोगकर्ता इंटरफ़ेस को अपेक्षित पूर्णता समय पर विफलता की घोषणा करने के बजाय उस प्रसार को सहन करना चाहिए।
])

